# Inner API library: keep every own-namespace symbol (functions, vtable,
# VTT, typeinfo, guard, thunk) written on mangled names; hide std inline
# instances, ffrt/emutls template leaks and _init/_fini. The mangled
# wildcard is feature-switch immune (new own symbols under OHOS:: are
# exported automatically).
{
  global:
    _Z*4OHOS*;
  local:
    *;
};
